export const metadata: Metadata = { title: "管理后台" }; export const dynamic = "force-dynamic";
export default async function AdminPage() { const month = new Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Shanghai", year: "numeric", month: "2-digit" }).format(new Date()); const [achievements,todos,footprints,inspirationCount,inspirationRun,recentErrors,latestBackup,database] = await Promise.all([prisma.achievement.findMany({orderBy:[{isPinned:"desc"},{startDate:"desc"}]}),prisma.todo.findMany({where:{isArchived:false},orderBy:{createdAt:"desc"}}),prisma.footprint.findMany({orderBy:{visitedAt:"desc"}}),prisma.inspirationItem.count({where:{monthKey:month}}),prisma.inspirationRun.findFirst({where:{monthKey:month},orderBy:{startedAt:"desc"}}),prisma.operationLog.count({where:{module:"monitoring",result:"failed",createdAt:{gte:new Date(Date.now()-7*86400000)}}}),prisma.backupRecord.findFirst({orderBy:{createdAt:"desc"}}),prisma.$queryRaw`SELECT 1`]); return <DashboardShell title="管理后台" subtitle="统一管理成就、待办和足迹。"><div className="admin-sections"><section className="admin-section"><ShareLinkManager /></section><AdminAlertPanel errors={recentErrors} cron={inspirationRun} backup={latestBackup} database={Boolean(database)} /><section className="admin-section"><div className="admin-section-heading"><div><p className="eyebrow">DATA SAFETY</p><h2>数据备份</h2></div></div><BackupManager /></section><section className="admin-section"><div className="admin-section-heading"><div><p className="eyebrow">AESTHETIC INSPIRATION</p><h2>审美灵感</h2></div><span>{month}</span></div><InspirationAdmin month={month} count={inspirationCount} failed={inspirationRun?.status === "failed" ? inspirationRun.errorMessage : null} /></section><section className="admin-section"><div className="admin-section-heading"><div><p className="eyebrow">ACHIEVEMENTS</p><h2>成就</h2></div><span>{achievements.length} 条</span></div><AchievementsManager initialItems={achievements.map(item=>({...item,startDate:item.startDate.toISOString(),endDate:item.endDate?.toISOString()||null,createdAt:item.createdAt.toISOString(),updatedAt:item.updatedAt.toISOString()}))}/></section><section className="admin-section"><div className="admin-section-heading"><div><p className="eyebrow">OPEN TASKS</p><h2>待办</h2></div><span>{todos.length} 条</span></div><TodosManager initialItems={todos.map(item=>({...item,dueDate:item.dueDate?.toISOString()||null,completedAt:item.completedAt?.toISOString()||null,archivedAt:item.archivedAt?.toISOString()||null,createdAt:item.createdAt.toISOString(),updatedAt:item.updatedAt.toISOString()}))}/></section><section className="admin-section"><div className="admin-section-heading"><div><p className="eyebrow">FOOTPRINTS</p><h2>足迹</h2></div><span>{footprints.length} 处</span></div><FootprintsManager initialItems={footprints.map(item=>({id:item.id,scope:item.scope,countryCode:item.countryCode,countryNameZh:item.countryNameZh,countryNameEn:item.countryNameEn,provinceCode:item.provinceCode,provinceNameZh:item.provinceNameZh,provinceNameEn:item.provinceNameEn,visited:item.visited}))}/></section></div></DashboardShell>; }

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { collect, loadBackup, removeBackup, saveBackup, scopes, type BackupScope } from "@/lib/backup";

export async function GET(request: Request) {
  const url = new URL(request.url); const action = url.searchParams.get("action");
  if (action === "export") {
    const scope = (scopes.includes((url.searchParams.get("scope") ?? "all") as BackupScope) ? url.searchParams.get("scope") : "all") as BackupScope;
    const format = url.searchParams.get("format") ?? "json"; const payload = await collect(scope);
    if (format === "csv") {
      const chunks = Object.entries(payload.data).map(([module, rows]) => { const list = rows as Record<string, unknown>[]; const keys = [...new Set(list.flatMap(row => Object.keys(row)))]; return `# ${module}\n${keys.join(",")}\n${list.map(row => keys.map(key => JSON.stringify(row[key] ?? "")).join(",")).join("\n")}`; }).join("\n\n");
      return new Response(chunks, { headers: { "Content-Type": "text/csv; charset=utf-8", "Content-Disposition": `attachment; filename=backup-${new Date().toISOString().slice(0, 10)}.csv` } });
    }
    return new Response(JSON.stringify(payload, null, 2), { headers: { "Content-Type": "application/json", "Content-Disposition": `attachment; filename=backup-${new Date().toISOString().slice(0, 10)}.json` } });
  }
  if (action === "download") { const record = await prisma.backupRecord.findUnique({ where: { id: Number(url.searchParams.get("id")) } }); if (!record) return NextResponse.json({ error: "备份不存在" }, { status: 404 }); const payload = await loadBackup(record.fileName); return new Response(JSON.stringify(payload, null, 2), { headers: { "Content-Type": "application/json", "Content-Disposition": `attachment; filename=${record.fileName}` } }); }
  return NextResponse.json(await prisma.backupRecord.findMany({ orderBy: { createdAt: "desc" } }));
}

export async function POST(request: Request) {
  const body = await request.json();
  if (body.action === "create") return NextResponse.json(await saveBackup("manual", body.scope ?? "all"));
  if (body.action === "delete") { const record = await prisma.backupRecord.findUnique({ where: { id: Number(body.id) } }); if (record) { await removeBackup(record.fileName); await prisma.backupRecord.delete({ where: { id: record.id } }); } return NextResponse.json({ ok: true }); }
  if (body.action === "preview") { const backup = body.backup; if (!backup || backup.version !== 1 || !backup.data) return NextResponse.json({ error: "文件结构或版本号无效" }, { status: 400 }); const result: Record<string, unknown> = {}; for (const [module, rows] of Object.entries(backup.data)) { const model = { achievements: "achievement", todos: "todo", footprints: "footprint", inspirations: "inspirationItem" }[module]; if (!model) continue; const ids = (rows as { id?: number }[]).map(row => row.id).filter(Boolean) as number[]; const existing = await (prisma as any)[model].count({ where: { id: { in: ids } } }); result[module] = { total: (rows as unknown[]).length, existing, added: (rows as unknown[]).length - existing }; } return NextResponse.json({ modules: result }); }
  if (body.action === "import") { const backup = body.backup; const mode = body.mode ?? "merge"; try { await prisma.$transaction(async tx => { for (const [module, rows] of Object.entries(backup.data)) { const model = { achievements: "achievement", todos: "todo", footprints: "footprint", inspirations: "inspirationItem" }[module] as any; if (!model) continue; const delegate = (tx as any)[model]; if (mode === "clear") await delegate.deleteMany({}); for (const raw of rows as any[]) { const data = { ...raw }; for (const key of ["createdAt", "updatedAt", "startDate", "endDate", "dueDate", "completedAt", "archivedAt", "visitedAt", "collectedAt", "startedAt", "finishedAt"]) if (data[key]) data[key] = new Date(data[key]); if (mode === "merge") { const found = data.id ? await delegate.findUnique({ where: { id: data.id } }) : null; if (found) continue; } await delegate.upsert({ where: { id: data.id }, create: data, update: mode === "overwrite" ? data : {} }); } } }); return NextResponse.json({ ok: true }); } catch (error) { return NextResponse.json({ error: error instanceof Error ? error.message : "导入失败，原有数据未修改" }, { status: 400 }); } }
  return NextResponse.json({ error: "未知操作" }, { status: 400 });
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { logOperation } from "@/lib/operation-log";
const models:any={achievements:"achievement",todos:"todo",footprints:"footprint",inspirations:"inspirationItem"};
export async function GET(){const out:any={};for(const [module,model] of Object.entries(models) as [string,string][])out[module]=await (prisma as any)[model].findMany({where:{isDeleted:true},orderBy:{deletedAt:"desc"}});return NextResponse.json(out)}
export async function POST(request:Request){const b=await request.json();const model=models[b.module];if(!model)return NextResponse.json({error:"模块无效"},{status:400});const ids=(b.ids??[b.id]).map(Number);for(const id of ids){if(b.action==="restore"){await (prisma as any)[model].update({where:{id},data:{isDeleted:false,deletedAt:null,deletedBy:null}});await logOperation({action:"restore",module:b.module,objectType:model,objectId:id})}else if(b.action==="purge"){await (prisma as any)[model].delete({where:{id}});await logOperation({action:"purge",module:b.module,objectType:model,objectId:id})}}return NextResponse.json({ok:true})}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { SESSION_COOKIE, verifySession } from "@/lib/auth";

const take = 5;
const contains = (q: string) => ({ contains: q });
const text = (value: string | null | undefined, q: string) => { const s = (value ?? "").replace(/\s+/g, " ").trim(); const i = s.toLocaleLowerCase().indexOf(q.toLocaleLowerCase()); return i > 35 ? `…${s.slice(i - 35, i + 75)}${s.length > i + 75 ? "…" : ""}` : s.slice(0, 110); };
const order = (title: string, q: string) => { const a = title.toLocaleLowerCase(), b = q.toLocaleLowerCase(); return a === b ? 0 : a.includes(b) ? 1 : 2; };
const parseTags = (s: string) => { try { return JSON.parse(s) as string[]; } catch { return []; } };

export async function GET(request: Request) {
  const token = request.headers.get("cookie")?.split(";").map((x) => x.trim()).find((x) => x.startsWith(`${SESSION_COOKIE}=`))?.slice(SESSION_COOKIE.length + 1);
  if (!(await verifySession(token))) return NextResponse.json({ error: "未登录" }, { status: 401 });
  const q = new URL(request.url).searchParams.get("q")?.trim() ?? "";
  if (!q) return NextResponse.json({ achievements: [], todos: [], footprints: [], inspirations: [] });
  const c = contains(q);
  const [achievements, todos, footprints, inspirations] = await Promise.all([
    prisma.achievement.findMany({ where: { isDeleted: false, OR: [{ title: c }, { description: c }, { awardDetails: c }, { organization: c }, { role: c }, { tags: c }, { type: c }] }, select: { id: true, title: true, type: true, description: true, awardDetails: true, organization: true }, take: 5 }),
    prisma.todo.findMany({ where: { isDeleted: false, OR: [{ title: c }, { description: c }, { tags: c }] }, select: { id: true, title: true, status: true, priority: true, isArchived: true, description: true }, take: 5 }),
    prisma.footprint.findMany({ where: { isDeleted: false, OR: [{ countryNameZh: c }, { countryNameEn: c }, { provinceNameZh: c }, { provinceNameEn: c }] }, select: { id: true, key: true, countryNameZh: true, countryNameEn: true, provinceNameZh: true, provinceNameEn: true, visited: true, note: true }, take: 5 }),
    prisma.inspirationItem.findMany({ where: { isDeleted: false, OR: [{ title: c }, { summary: c }, { details: c }, { tags: c }, { category: c }, { subCategory: c }] }, select: { id: true, title: true, category: true, subCategory: true, summary: true, details: true }, take: 5 }),
  ]);
  return NextResponse.json({
    achievements: achievements.sort((a, b) => order(a.title, q) - order(b.title, q)).slice(0, take).map((x) => ({ id: x.id, title: x.title, type: x.type, snippet: text(x.description || x.awardDetails || x.organization, q), url: `/achievements?focus=${x.id}` })),
    todos: todos.sort((a, b) => order(a.title, q) - order(b.title, q)).slice(0, take).map((x) => ({ id: x.id, title: x.title, status: x.status, priority: x.priority, isArchived: x.isArchived, snippet: text(x.description, q), url: `/todos?focus=${x.id}` })),
    footprints: footprints.slice(0, take).map((x) => ({ id: x.id, title: x.provinceNameZh || x.countryNameZh || x.provinceNameEn || x.countryNameEn || x.key, subtitle: [x.countryNameEn, x.provinceNameEn].filter(Boolean).join(" · "), visited: x.visited, snippet: x.note || "足迹记录", url: "/footprints" })),
    inspirations: inspirations.sort((a, b) => order(a.title, q) - order(b.title, q)).slice(0, take).map((x) => ({ id: x.id, title: x.title, category: x.category, subCategory: x.subCategory, snippet: text(x.summary || x.details, q), url: `/inspiration?focus=${x.id}` })),
  });
}

import Link from "next/link";
import { Award, CalendarClock, CheckCircle2, Clock3, MapPinned, Pin, Trophy } from "lucide-react";
import { prisma } from "@/lib/prisma";
import { DashboardShell } from "@/components/dashboard-shell";
import { PixelWelcome } from "@/components/pixel-welcome";
import { HomeActions } from "@/components/home-actions";
import { LazyFootprintsPicker } from "@/components/lazy-footprints-picker";
import { runTodoCleanup } from "@/lib/todo-maintenance";
import { HomeLiveRefresh } from "@/components/home-live-refresh";
import { HomeDueReminder } from "@/components/home-due-reminder";

export const dynamic = "force-dynamic";
const priorityWeight:Record<string,number>={high:0,medium:1,low:2};
function dateLabel(date:Date){return date.toLocaleDateString("zh-CN",{year:"numeric",month:"2-digit",day:"2-digit"})}

export default async function Home(){
  await runTodoCleanup();
  const reminderStart=new Date();reminderStart.setHours(0,0,0,0);const reminderEnd=new Date(reminderStart);reminderEnd.setDate(reminderEnd.getDate()+1);const dueToday=await prisma.todo.findMany({where:{isArchived:false,isDeleted:false,status:{not:"done"},dueDate:{gte:reminderStart,lt:reminderEnd}},select:{id:true,title:true}});for(const todo of dueToday){const exists=await prisma.notification.findFirst({where:{todoId:todo.id,type:"dueSoon"}});if(!exists)await prisma.notification.create({data:{type:"dueSoon",title:"待办提醒",message:`“${todo.title}”今天到期，请记得完成。`,todoId:todo.id}})}
  const now=new Date();const dueLimit=new Date(now);dueLimit.setDate(dueLimit.getDate()+7);
  const [achievementCount,todoCount,dueSoonCount,countryRows,inspirationCount,footprintItems,recentAchievements,openTodos,timeline,doneTodoCount,totalTodoCount]=await Promise.all([
    prisma.achievement.count(),
    prisma.todo.count({where:{isArchived:false,isDeleted:false,status:{not:"done"}}}),
    prisma.todo.count({where:{isArchived:false,isDeleted:false,status:{not:"done"},dueDate:{gte:now,lte:dueLimit}}}),
    prisma.footprint.findMany({where:{visited:true,scope:"country",countryCode:{not:null}},select:{countryCode:true},distinct:["countryCode"]}),
    prisma.inspirationItem.count({where:{isDeleted:false}}),
    prisma.footprint.findMany({where:{visited:true},select:{id:true,scope:true,countryCode:true,countryNameZh:true,countryNameEn:true,provinceCode:true,provinceNameZh:true,provinceNameEn:true,visited:true}}),
    prisma.achievement.findMany({orderBy:[{isPinned:"desc"},{startDate:"desc"}],take:4}),
    prisma.todo.findMany({where:{isArchived:false,isDeleted:false,status:{not:"done"}},take:30}),
    prisma.achievement.findMany({where:{isDeleted:false},orderBy:{startDate:"desc"}}),
    prisma.todo.count({where:{isArchived:false,status:"done"}}),
    prisma.todo.count({where:{isArchived:false}}),
  ]);
  const recentTodos=openTodos.sort((a,b)=>{const da=a.dueDate?.getTime()??Number.MAX_SAFE_INTEGER;const db=b.dueDate?.getTime()??Number.MAX_SAFE_INTEGER;return da-db||(priorityWeight[a.priority]??9)-(priorityWeight[b.priority]??9)}).slice(0,4);
  return <HomeLiveRefresh><DashboardShell><PixelWelcome/><section className="home-layout"><div className="home-content">
    <section className="profile-intro"><div><p className="eyebrow">ABOUT THIS SPACE</p><h1>你好，这里是我的个人档案。</h1><p>我在这里记录完成的项目、正在推进的计划，以及亲自去过的地方。每一条记录都保留时间，也保留当时为什么出发。</p></div><HomeActions/></section>
    <section className="home-stats" aria-label="个人统计"><article><Award/><span>成就数量</span><strong>{achievementCount}</strong></article><article><Clock3/><span>待办完成率</span><strong>{Math.round(doneTodoCount / Math.max(totalTodoCount,1) * 100)}%</strong></article><article><MapPinned/><span>去过国家数</span><strong>{countryRows.length}</strong></article><article><CalendarClock/><span>灵感条目</span><strong>{inspirationCount}</strong></article></section>
    <div className="home-lists"><section className="paper-card compact-card"><div className="section-heading"><div><span>ACHIEVEMENTS</span><h2>最近成就</h2></div><Link href="/achievements">查看全部</Link></div>{recentAchievements.length?<div className="record-list">{recentAchievements.map(item=><Link href={`/achievements/${item.id}`} className="record-row" key={item.id}><div className="record-mark">{item.isPinned?<Pin size={15}/>:<Trophy size={15}/>}</div><div><h3>{item.title}</h3><p>{item.type} · {item.organization||"未填写机构"}</p></div><time>{dateLabel(item.startDate)}</time></Link>)}</div>:<div className="empty-state">还没有成就记录。</div>}</section>
      <section className="paper-card compact-card"><div className="section-heading"><div><span>OPEN TASKS</span><h2>最近待办</h2></div><Link href="/todos">查看全部</Link></div>{recentTodos.length?<div className="record-list">{recentTodos.map(item=><Link href="/todos" className="record-row" key={item.id}><div className="record-mark"><CheckCircle2 size={15}/></div><div><h3>{item.title}</h3><p>{item.status==="doing"?"进行中":"待开始"} · {item.priority==="high"?"高优先级":item.priority==="medium"?"中优先级":"低优先级"}</p></div><time>{item.dueDate?dateLabel(item.dueDate):"未设日期"}</time></Link>)}</div>:<div className="empty-state">目前没有未完成待办。</div>}</section></div>
    <section className="footprint-preview"><div className="section-heading"><div><span>FOOTPRINTS</span><h2>足迹缩略图</h2></div><Link href="/footprints">打开足迹</Link></div><LazyFootprintsPicker initialItems={footprintItems} preview/></section>
  </div><aside className="timeline-panel"><div className="timeline-heading"><p className="eyebrow">ALL ACHIEVEMENTS</p><h2>成就时间轴</h2><span>{timeline.length} 条成就记录</span></div>{timeline.length?<div className="timeline-scroll">{timeline.map(item=><Link href={`/achievements/${item.id}`} className="timeline-item" key={item.id}><span className="timeline-dot"/><div><span className="badge">{item.type}</span><h3>{item.title}</h3><p>{dateLabel(item.startDate)} - {item.endDate?dateLabel(item.endDate):"至今"}</p></div></Link>)}</div>:<div className="timeline-empty"><Award/><p>暂无成就记录。添加成就后会显示在这里。</p></div>}</aside></section></DashboardShell></HomeLiveRefresh>;
}

import { notFound } from "next/navigation";import { prisma, setUserScope } from "@/lib/prisma";
