import { Download, RefreshCw, Trash2, Upload } from "lucide-react";
type RecordItem={id:number;type:string;scope:string;fileSize:number;createdAt:string};const labels:Record<string,string>={all:"全部数据",achievements:"成就",todos:"待办",footprints:"足迹",inspirations:"灵感"};
export function BackupManager(){const[records,setRecords]=useState<RecordItem[]>([]),[scope,setScope]=useState("all"),[message,setMessage]=useState("");async function refresh(){setRecords(await(await fetch("/api/backups")).json())}useEffect(()=>{refresh()},[]);function exp(format:string){location.href=`/api/backups?action=export&scope=${scope}&format=${format}`}async function create(){const d=await(await fetch("/api/backups",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"create",scope})})).json();setMessage(d.status==="success"?"备份已完成":d.errorMessage??"备份失败");refresh()}async function imp(file:File){try{const backup=JSON.parse(await file.text()),p=await(await fetch("/api/backups",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"preview",backup})})).json();if(p.error)throw Error(p.error);const s=Object.entries(p.modules).map(([k,v]:any)=>`${labels[k]??k} ${v.total} 条，新增 ${v.added} 条`).join("；"),mode=prompt(`导入预览：${s}\n请输入模式：merge 合并，overwrite 覆盖，clear 清空后导入`,"merge");if(!mode||!["merge","overwrite","clear"].includes(mode)||!confirm("导入会修改数据库，确定继续吗？"))return;const r=await(await fetch("/api/backups",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"import",backup,mode})})).json();setMessage(r.error??"导入完成")}catch(e){setMessage(e instanceof Error?e.message:"文件读取失败")}}return <section className="backup-panel"><div className="backup-tools"><div><h3>数据备份与恢复</h3><p>JSON 用于恢复，CSV 方便查看。</p></div><select className="field-select backup-scope" value={scope} onChange={e=>setScope(e.target.value)}>{Object.entries(labels).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select><button className="primary-button" onClick={()=>exp("json")}><Download size={16}/>导出 JSON</button><button className="ghost-button" onClick={()=>exp("csv")}>导出 CSV</button><button className="ghost-button" onClick={create}><RefreshCw size={16}/>手动备份</button><label className="ghost-button"><Upload size={16}/>导入数据<input type="file" accept=".json" hidden onChange={e=>e.target.files?.[0]&&imp(e.target.files[0])}/></label></div>{message&&<p className="backup-message">{message}</p>}<table className="data-table"><thead><tr><th>时间</th><th>类型</th><th>范围</th><th>大小</th><th>操作</th></tr></thead><tbody>{records.map(i=><tr key={i.id}><td>{new Date(i.createdAt).toLocaleString("zh-CN")}</td><td>{i.type==="auto"?"自动":"手动"}</td><td>{labels[i.scope]??i.scope}</td><td>{i.fileSize?`${(i.fileSize/1024).toFixed(1)} KB`:"-"}</td><td><a className="icon-button" href={`/api/backups?action=download&id=${i.id}`}><Download size={16}/></a><button className="icon-button" onClick={async()=>{if(!confirm("确定删除这份备份吗？"))return;await fetch("/api/backups",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"delete",id:i.id})});refresh()}}><Trash2 size={16}/></button></td></tr>)}</tbody></table></section>}

