"use client";
import { useEffect, useMemo, useRef, useState } from "react";
import { Search, LoaderCircle } from "lucide-react";
import { usePathname, useRouter } from "next/navigation";

const names: Record<string, string> = { achievements: "成就", todos: "待办", footprints: "足迹", inspirations: "审美灵感" };
function Highlight({ value, q }: { value?: string; q: string }) { if (!value) return null; const safe = q.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"); return <>{value.split(new RegExp(`(${safe})`, "ig")).map((part, i) => part.toLowerCase() === q.toLowerCase() ? <mark key={i}>{part}</mark> : part)}</>; }
export function GlobalSearch() {
  const router = useRouter(); const pathname = usePathname(); const input = useRef<HTMLInputElement>(null); const [open, setOpen] = useState(false), [q, setQ] = useState(""), [data, setData] = useState<Record<string, any[]>>({}), [loading, setLoading] = useState(false), [error, setError] = useState(""), [selected, setSelected] = useState(0);
  useEffect(() => { const onKey = (e: KeyboardEvent) => { if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "k") { e.preventDefault(); setOpen(true); } if (e.key === "Escape") setOpen(false); }; window.addEventListener("keydown", onKey); return () => window.removeEventListener("keydown", onKey); }, []);
  useEffect(() => { if (!open) return; const onPointerDown = (e: PointerEvent) => { const target = e.target as HTMLElement; if (!target.closest(".global-search-modal")) { setOpen(false); setQ(""); setData({}); } }; document.addEventListener("pointerdown", onPointerDown); return () => document.removeEventListener("pointerdown", onPointerDown); }, [open]);
  useEffect(() => { if (open) setTimeout(() => input.current?.focus(), 0); }, [open]);
  useEffect(() => { if (!q.trim()) { setData({}); return; } const timer = setTimeout(async () => { setLoading(true); setError(""); try { const r = await fetch(`/api/search?q=${encodeURIComponent(q)}`); if (!r.ok) throw new Error(); setData(await r.json()); setSelected(0); } catch { setError("搜索失败，请稍后重试。"); } finally { setLoading(false); } }, 300); return () => clearTimeout(timer); }, [q]);
  const groups = useMemo(() => Object.keys(names).map((key) => ({ key, items: data[key] || [] })).filter((x) => x.items.length), [data]); const flat = groups.flatMap((x) => x.items);
  useEffect(() => { const target = sessionStorage.getItem("global-search-target"); if (!target) return; const timer = setTimeout(() => { const nodes = [...document.querySelectorAll("h1,h2,h3,strong")]; const match = nodes.find((node) => node.textContent?.trim() === target); const card = match?.closest("article,section,.inspiration-row,.todo-item"); if (card) { card.scrollIntoView({ behavior: "smooth", block: "center" }); card.classList.add("global-search-focus"); setTimeout(() => card.classList.remove("global-search-focus"), 1800); sessionStorage.removeItem("global-search-target"); } }, 450); return () => clearTimeout(timer); }, [pathname]);
  const close = () => { setOpen(false); setQ(""); setData({}); }; const go = (item: any) => { sessionStorage.setItem("global-search-target", item.title); close(); router.push(item.url); };
  const keyboard = async (e: React.KeyboardEvent) => { if (e.key === "ArrowDown") { e.preventDefault(); setSelected((x) => Math.min(x + 1, Math.max(flat.length - 1, 0))); } else if (e.key === "ArrowUp") { e.preventDefault(); setSelected((x) => Math.max(x - 1, 0)); } else if (e.key === "Enter") { e.preventDefault(); if (flat[selected]) { go(flat[selected]); return; } if (!q.trim()) return; setLoading(true); try { const response = await fetch(`/api/search?q=${encodeURIComponent(q.trim())}`); if (!response.ok) throw new Error(); const result = await response.json() as Record<string, any[]>; const first = ["achievements", "todos", "footprints", "inspirations"].flatMap((key) => result[key] || [])[0]; if (first) go(first); else setData(result); } catch { setError("搜索失败，请稍后重试。"); } finally { setLoading(false); } } };
  return <><div className="global-search-entry"><Search size={17}/><input value={q} onChange={(e) => { setQ(e.target.value); setOpen(true); }} onFocus={() => setOpen(true)} onKeyDown={keyboard} placeholder="搜索成就、待办、足迹、灵感..." aria-label="全局搜索"/><kbd>Ctrl K</kbd></div><button className="global-search-mobile" onClick={() => setOpen(true)} aria-label="打开全局搜索"><Search size={19}/></button>{open && <div className="global-search-overlay" onMouseDown={(e) => e.target === e.currentTarget && close()}><div className="global-search-modal" role="dialog" aria-modal="true"><div className="global-search-modal-input"><Search size={19}/><input ref={input} autoFocus value={q} onChange={(e) => setQ(e.target.value)} onKeyDown={keyboard} placeholder="搜索成就、待办、足迹、灵感..." aria-label="搜索站内内容"/><kbd>Esc</kbd></div>{loading && <p className="global-search-status"><LoaderCircle className="spin" size={18}/>正在搜索...</p>}{error && <p className="global-search-status error">{error}</p>}{!loading && !error && q && !flat.length && <p className="global-search-status">没有找到相关内容，试试其他关键词。</p>}<div className="global-search-results">{groups.map((group) => <section key={group.key}><header><h2>{names[group.key]}</h2>{group.items.length >= 5 && <a href={`/${group.key === "inspirations" ? "inspiration" : group.key}?q=${encodeURIComponent(q)}`}>查看全部</a>}</header>{group.items.map((item, i) => <button key={`${group.key}-${item.id}`} className={`global-search-result ${flat.indexOf(item) === selected ? "selected" : ""}`} onClick={() => go(item)}><strong><Highlight value={item.title} q={q}/></strong><span className="badge">{item.status || item.type || item.category || (item.visited ? "已去过" : "未去过")}</span><p><Highlight value={item.snippet || item.subtitle} q={q}/></p></button>)}</section>)}</div></div></div>}</>;
}

"use client";
import { useEffect, useState } from "react";
type Item={id:number;title:string;summary:string;reviewStatus:string;sourceDomain:string};
const labels={pending:"待审核",approved:"已通过",rejected:"已拒绝"} as Record<string,string>;
export function InspirationAdmin({month,count,failed}:{month:string;count:number;failed?:string|null}){const[items,setItems]=useState<Item[]>([]);const[runs,setRuns]=useState<any[]>([]);const[filter,setFilter]=useState("all");const[loading,setLoading]=useState(false);async function load(){const d=await fetch(`/api/inspiration/admin?month=${month}`).then(r=>r.json());setItems(d.items||[]);setRuns(d.runs||[])}useEffect(()=>{load()},[month]);async function update(id:number,body:any){await fetch(`/api/inspiration/admin/${id}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});load()}async function refresh(force=false){const reason=force?prompt("请输入强制重跑原因："):null;if(force&&!reason?.trim())return;setLoading(true);await fetch("/api/inspiration/refresh",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({monthKey:month,force,forcedReason:reason})});setLoading(false);load()}const visible=items.filter(i=>filter==="all"||i.reviewStatus===filter);return <div className="inspiration-admin"><div className="admin-toolbar"><span>本月共 {count} 条，待审核 {items.filter(i=>i.reviewStatus==="pending").length} 条</span><select className="field-select" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">全部状态</option><option value="pending">待审核</option><option value="approved">已通过</option><option value="rejected">已拒绝</option></select><button className="primary-button" onClick={()=>refresh()} disabled={loading}>{loading?"采集中…":"立即刷新"}</button><button className="ghost-button" onClick={()=>refresh(true)} disabled={loading}>强制重跑</button></div>{failed&&<p className="admin-warning">上次任务失败：{failed}</p>}<div className="inspiration-review-list">{visible.map(item=><article className="review-card" key={item.id}><div><span className={`review-badge review-${item.reviewStatus}`}>{labels[item.reviewStatus]}</span><input className="field-input" defaultValue={item.title} onBlur={e=>update(item.id,{title:e.currentTarget.value})}/><p>{item.summary}</p><small>来源：{item.sourceDomain||"未记录"}</small></div><div className="review-actions"><button className="ghost-button" onClick={()=>update(item.id,{reviewStatus:"approved"})}>通过</button><button className="ghost-button" onClick={()=>update(item.id,{reviewStatus:"rejected"})}>拒绝</button><button className="danger-button" onClick={async()=>{if(confirm("确认删除这条灵感？")){await fetch(`/api/inspiration/admin/${item.id}`,{method:"DELETE"});load()}}}>删除</button></div></article>)}</div><details className="run-history"><summary>采集运行记录（最近 {runs.length} 次）</summary>{runs.map(run=><p key={run.id}>{new Date(run.startedAt).toLocaleString()} · {run.triggerType} · {run.status} · {run.collectedCount||run.itemCount} 条 · 待审核 {run.pendingCount||0}{run.errorMessage?` · ${run.errorMessage}`:""}</p>)}</details></div>}

"use client";
import { useEffect,useState } from "react";
export function InspirationBoardV2(){const[items,setItems]=useState<any[]>([]);const[month]=useState(new Intl.DateTimeFormat("en-CA",{timeZone:"Asia/Shanghai",year:"numeric",month:"2-digit"}).format(new Date()));const[detail,setDetail]=useState<any>(null);useEffect(()=>{fetch(`/api/inspiration?month=${month}`).then(r=>r.json()).then(d=>setItems(d.items||[]))},[month]);return <div className="paper-card"><p className="eyebrow">{month}</p><h2>本月审美灵感</h2>{items.length?items.map(item=><article className="inspiration-row" key={item.id} onClick={()=>setDetail(item)}><span><strong>{item.title}</strong><small>{item.summary}</small></span></article>):<div className="empty-state">暂无灵感数据。</div>}{detail&&<div className="dialog-backdrop" onClick={()=>setDetail(null)}><section className="form-card inspiration-detail" onClick={e=>e.stopPropagation()}><button className="icon-button" onClick={()=>setDetail(null)}>×</button><h2>{detail.title}</h2><p>{detail.summary}</p><p>{detail.details}</p><button className="danger-button" onClick={async()=>{if(!confirm("确定删除这条灵感吗？"))return;const r=await fetch(`/api/inspiration?id=${detail.id}`,{method:"DELETE"});if(r.ok){setItems(v=>v.filter(x=>x.id!==detail.id));setDetail(null)}}}>删除这条灵感</button></section></div>}</div>}

"use client";
import { useEffect, useMemo, useState } from "react";
const CATEGORIES = { outfit: { label: "穿搭美学", tags: { color: "配色趋势", style: "风格趋势", element: "元素与版型" } }, fashion: { label: "时尚前沿", tags: { runway: "时装秀与秀场趋势", accessory: "配饰与配件", brand: "品牌与单品动态" } }, creative: { label: "创意灵感", tags: { graphic: "平面设计", remake: "服饰 Remake", object: "物品创意用法" } } } as const;
type Item = { id:number; category:string; subCategory:string; title:string; summary:string; details:string; typicalExamples:string[]; sourceLinks:{title:string;url:string}[]; tags:string[]; monthKey:string };
const tagNames: Record<string,string> = Object.values(CATEGORIES).flatMap(x=>Object.entries(x.tags)).reduce((a,[k,v])=>({...a,[k]:v}),{});
const fallback = "https://images.unsplash.com/photo-1529139574466-a303027c1d8b?w=900&q=80";
export function InspirationBoard(){const [month,setMonth]=useState(new Intl.DateTimeFormat("en-CA",{timeZone:"Asia/Shanghai",year:"numeric",month:"2-digit"}).format(new Date()));const[items,setItems]=useState<Item[]>([]);const[selected,setSelected]=useState<string|null>(null);const[detail,setDetail]=useState<Item|null>(null);const[tab,setTab]=useState("");useEffect(()=>{fetch(`/api/inspiration?month=${month}`).then(r=>r.json()).then(d=>setItems(d.items||[]))},[month]);const grouped=useMemo(()=>Object.keys(CATEGORIES).map(category=>({category,items:items.filter(i=>i.category===category)})),[items]);const active=selected?items.filter(i=>i.category===selected):[];const sub=tab||active[0]?.subCategory||"";return <div className="inspiration-board"><div className="inspiration-toolbar"><button className="ghost-button" onClick={()=>setMonth(prev=>{const d=new Date(`${prev}-15`);d.setMonth(d.getMonth()-1);return d.toISOString().slice(0,7)})}>‹ 上月</button><input type="month" value={month} onChange={e=>setMonth(e.target.value)} /><button className="ghost-button" onClick={()=>setMonth(prev=>{const d=new Date(`${prev}-15`);d.setMonth(d.getMonth()+1);return d.toISOString().slice(0,7)})}>下月 ›</button></div><div className="inspiration-categories">{grouped.map(({category,items:rows})=><button className="inspiration-category" key={category} onClick={()=>{setSelected(category);setTab("")}}><span className="inspiration-swatch"/><div><p>{CATEGORIES[category as keyof typeof CATEGORIES].label}</p><strong>{rows.length} 条</strong><small>{rows.length?rows[0].summary:"本月还没有收集到条目。"}</small></div></button>)}</div>{!items.length&&<div className="empty-state">{month} 暂无灵感数据。采集任务完成后会显示在这里。</div>}{selected&&<div className="dialog-backdrop" onClick={()=>setSelected(null)}><section className="form-card inspiration-index" onClick={e=>e.stopPropagation()}><header><div><p className="eyebrow">{month}</p><h2>{CATEGORIES[selected as keyof typeof CATEGORIES].label}</h2></div><button className="icon-button" onClick={()=>setSelected(null)}>×</button></header><div className="inspiration-tabs">{Object.entries(CATEGORIES[selected as keyof typeof CATEGORIES].tags).map(([key,label])=><button className={sub===key?"active":""} key={key} onClick={()=>setTab(key)}>{label} ({active.filter(i=>i.subCategory===key).length})</button>)}</div><div className="inspiration-list">{active.filter(i=>i.subCategory===sub).map(item=><button className="inspiration-row" key={item.id} onClick={()=>setDetail(item)}><img src={item.typicalExamples[0]||fallback} onError={e=>e.currentTarget.src=fallback} alt=""/><span><strong>{item.title}</strong><small>{item.summary}</small></span></button>)}</div><button className="ghost-button" onClick={()=>setSelected(null)}>关闭</button></section></div>}{detail&&<div className="dialog-backdrop" onClick={()=>setDetail(null)}><section className="form-card inspiration-detail" onClick={e=>e.stopPropagation()}><button className="icon-button close-detail" onClick={()=>setDetail(null)}>×</button><p className="eyebrow">{CATEGORIES[detail.category as keyof typeof CATEGORIES].label} · {tagNames[detail.subCategory]}</p><h2>{detail.title}</h2><p>{detail.summary}</p><div className="detail-copy">{detail.details.split("\n").map((p,i)=><p key={i}>{p}</p>)}</div><div className="inspiration-gallery">{(detail.typicalExamples.length?detail.typicalExamples:[fallback]).map(url=><img key={url} src={url} onError={e=>e.currentTarget.src=fallback} alt={detail.title}/>)}</div><h3>原始链接</h3>{detail.sourceLinks.map(link=><a key={link.url} href={link.url} target="_blank" rel="noreferrer">{link.title} ↗</a>)}<small className="cell-note">采集月份：{detail.monthKey}</small></section></div>}</div>}

