pan>}</div><div className="field"><label>优先级</label><select className="field-select" {...register("priority")}><option value="low">低</option><option value="medium">中</option><option value="high">高</option></select></div><label className="switch-label"><input type="checkbox" {...register("isPublic")}/>公开记录</label><div className="field full"><label className="switch-label"><input type="checkbox" checked={hasDueDate} onChange={event=>setHasDueDate(event.target.checked)}/>设置截止日期</label>{hasDueDate?<DateWheel value={dueDate} onChange={value=>setValue("dueDate",value,{shouldValidate:true})}/>:<div className="ongoing-note">未设置截止日期。</div>}</div><div className="field full"><label>描述</label><textarea className="field-textarea" rows={4} {...register("description")}/>{errors.description&&<span className="field-error">{errors.description.message}</span>}</div><div className="field full"><label>标签</label><input className="field-input" placeholder="多个标签用逗号分隔" {...register("tags")}/>{errors.tags&&<span className="field-error">{errors.tags.message}</span>}</div></div>{submitError&&<div className="form-submit-error" role="alert">{submitError}</div>}<div className="form-actions sticky-actions"><DialogClose asChild><button type="button" className="ghost-button">取消</button></DialogClose><button className="primary-button" disabled={isSubmitting}>{isSubmitting?<><Loader2 size={16} className="spin"/>正在保存</>:<>{initial?<Pencil size={16}/>:<Plus size={16}/>}保存</>}</button></div></form></DialogContent></Dialog>}

